pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz on from address, value v, decimals, and number of tos; we must supply a real contract address
    function testFuzz_property(address from, uint256 v, uint256 _decimals, uint8 tosLen) public {
        // Keep tosLen in a reasonable range but allow 1..10
        uint8 len = tosLen % 10 + 1; // ensure >=1 so require(_tos.length > 0) holds

        // Deploy a benign callee contract whose fallback always returns (i.e., does not revert)
        CallerResponder responder = new CallerResponder();

        // Build an array of recipient addresses (all set to some valid contract address which will accept the call)
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(responder);
        }

        // Bound decimals to reasonable range to avoid overflow in multiplication
        uint256 decimals = _decimals % 18; // 0..17

        // Call transfer and capture the returned boolean using try/catch as required
        bool ok;
        try c.transfer(from, address(responder), tos, v, decimals) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // The reference implementation always returns true for any non-empty tos array when the low-level calls do not revert.
        // Assert that c.transfer(...) returned true. (This will pass on the reference and fail on the mutant for some inputs.)
        assertTrue(ok);
    }
}

// Minimal benign responder: accepts any call and returns successfully
contract CallerResponder {
    fallback() external payable {
        // do nothing, just return successfully
    }

    receive() external payable {}
}

