// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller (from), the callee behavior is provided by a deployed Reverter helper,
    // fuzz the number of recipients and a value/decimals; at least one recipient is required
    function testFuzz_property(address from, uint256 v, uint8 decimals, uint256 tosCount) public {
        // keep tosCount reasonably bounded but allow zero to be filtered by vm.assume
        tosCount = bound(tosCount, 0, 8);
        vm.assume(tosCount > 0); // admissible domain per contract's require(_tos.length > 0)

        // deploy adversarial callee that always reverts when called
        Reverter rev = new Reverter();

        // build _tos array with the adversarial callee repeated tosCount times
        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) tos[i] = address(rev);

        // call transfer and observe whether it completes or reverts
        bool ok;
        try c.transfer(from, address(rev), tos, v, uint(decimals)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always attempts the external calls and thus
        // when the callee reverts, c.transfer must revert (so ok == false).
        // The mutant that returns early would return true (ok == true) and thus
        // violate this property for some inputs (here any with tosCount>0).
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable { revert("revert"); }
}
